-- Reference migration for fresh PostgreSQL deployments. EF's EnsureCreated path is used by the local container.
CREATE TABLE IF NOT EXISTS "Users" ("Id" uuid PRIMARY KEY, "Email" varchar(320) NOT NULL UNIQUE, "PasswordHash" text NOT NULL, "DisplayName" text NOT NULL, "CreatedAtUtc" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "UserPreferences" ("UserId" uuid PRIMARY KEY REFERENCES "Users"("Id") ON DELETE CASCADE, "DarkMode" boolean NOT NULL DEFAULT true, "DefaultView" text NOT NULL DEFAULT 'kanban', "InterviewRounds" integer NOT NULL DEFAULT 3, "MfaEnabled" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS "JobApplications" ("Id" uuid PRIMARY KEY, "UserId" uuid NOT NULL REFERENCES "Users"("Id") ON DELETE CASCADE, "Company" varchar(200) NOT NULL, "Title" varchar(300) NOT NULL, "Description" text NOT NULL, "Skills" text NOT NULL, "Pay" text NOT NULL, "Location" text NOT NULL, "Nickname" text NOT NULL, "SourceUrl" text NULL, "Status" varchar(30) NOT NULL, "InterviewRound" integer NULL, "AppliedAtUtc" timestamptz NOT NULL, "UpdatedAtUtc" timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS "IX_JobApplications_UserId_Status" ON "JobApplications" ("UserId", "Status");
